// Unifies Typeform / HubSpot / Apollo webhooks AND plain sheet rows into one lead shape.
const clean = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const out = [];
$input.all().forEach((item, idx) => {
  const j = item.json || {};
  const b = (j.body && typeof j.body === 'object') ? j.body : null;
  let l = {};

  if (b && b.form_response) {                       // ---- Typeform
    const ans = b.form_response.answers || [];
    const byRef = (r) => {
      const a = ans.find(x => x.field && x.field.ref === r);
      return a ? (a.text ?? a.email ?? a.phone_number ?? a.number ?? '') : '';
    };
    const em = ans.find(x => x.type === 'email');
    const ph = ans.find(x => x.type === 'phone_number');
    l = { source: 'typeform', full_name: byRef('full_name'), email: em ? em.email : '',
          phone: ph ? ph.phone_number : '', job_title: byRef('job_title'),
          company_name: byRef('company_name'), message: byRef('message') };
  } else if (b && b.properties) {                   // ---- HubSpot
    const p = b.properties;
    const v = (k) => (p[k] && typeof p[k] === 'object') ? p[k].value : p[k];
    l = { source: 'hubspot', full_name: [v('firstname'), v('lastname')].filter(Boolean).join(' '),
          email: v('email'), phone: v('phone') || v('mobilephone'), job_title: v('jobtitle'),
          company_name: v('company'), message: v('message'), website: v('website') };
  } else if (b && b.person) {                       // ---- Apollo
    const p = b.person; const o = p.organization || b.organization || {};
    l = { source: 'apollo', full_name: p.name || [p.first_name, p.last_name].filter(Boolean).join(' '),
          email: p.email, phone: (p.phone_numbers && p.phone_numbers[0] && p.phone_numbers[0].sanitized_number) || p.phone,
          job_title: p.title, company_name: o.name, website: o.website_url || o.primary_domain,
          hint_employees: o.estimated_num_employees, message: '' };
  } else {                                          // ---- flat JSON or Google Sheet row
    const r = b || j;
    l = { source: r.source || 'sheet_test', full_name: r.full_name || r.name, email: r.email,
          phone: r.phone, job_title: r.job_title || r.title, company_name: r.company_name || r.company,
          message: r.message, website: r.website, hint_employees: r.employees,
          lead_id: r.lead_id, received_at: r.received_at };
  }

  const email = clean(l.email).toLowerCase();
  const emailDomain = email.includes('@') ? email.split('@').pop() : '';
  const web = clean(l.website).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];
  let phone = clean(l.phone).replace(/[^\d+]/g, '');
  if (phone && !phone.startsWith('+')) phone = '+' + phone;   // assumes country code is included

  out.push({ json: {
    lead_id: clean(l.lead_id) || ('LD-' + Date.now().toString(36) + '-' + idx),
    received_at: clean(l.received_at) || new Date().toISOString(),
    source: clean(l.source),
    full_name: clean(l.full_name),
    first_name: clean(l.full_name).replace(/^(dr|mr|mrs|ms)\.?\s+/i, '').split(' ')[0] || 'there',
    email, email_domain: emailDomain,
    phone,
    job_title: clean(l.job_title),
    company_name: clean(l.company_name),
    domain: web || emailDomain,
    message: clean(l.message),
    hint_employees: l.hint_employees ?? null,
  }});
});
return out;

// Merges enrichment + ICP rules, then computes a deterministic 0-100 rule score.
const leads = $('Unify Lead Formats').all().map(i => i.json);
const enrichRows = $('Read Enrichment Data').all().map(i => i.json);
const ruleRows = $('Read ICP Rules from Sheets').all().map(i => i.json);

const R = {};
ruleRows.forEach(r => { if (r.key !== undefined && String(r.key).trim() !== '') R[String(r.key).trim()] = r.value; });
const has = (k) => R[k] !== undefined && String(R[k]).trim() !== '';
const num = (k, d) => { if (!has(k)) return d; const v = Number(String(R[k]).replace(/[^0-9.\-]/g, '')); return isNaN(v) ? d : v; };
const str = (k, d) => has(k) ? String(R[k]).trim() : d;
const list = (k, d) => has(k) ? String(R[k]).split(',').map(s => s.trim().toLowerCase()).filter(Boolean) : d;
const toNum = (v) => { if (v === undefined || v === null || v === '') return null; const n = Number(String(v).replace(/[^0-9.]/g, '')); return isNaN(n) ? null : n; };
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const hasKw = (text, kws) => kws.some(k => new RegExp('(^|[^a-z])' + esc(k) + '([^a-z]|$)', 'i').test(text));

const FREE = list('free_email_domains', ['gmail.com', 'yahoo.com', 'outlook.com', 'hotmail.com']);
const INDUSTRIES = list('target_industries', []);
const EXEC = list('title_exec_keywords', ['ceo', 'cto', 'chief', 'founder', 'owner', 'president', 'vp']);
const DIR = list('title_director_keywords', ['director', 'head']);
const MGR = list('title_manager_keywords', ['manager']);
const DQ = list('title_disqualify_keywords', ['student', 'intern', 'freelancer']);

const T1_EMP = num('tier1_min_employees', 1000), T1_REV = num('tier1_min_revenue', 2+1234567890);
const T2_EMP = num('tier2_min_employees', 50),   T2_REV = num('tier2_min_revenue', 5000000);

const cfg = {
  tier1_min_score: num('tier1_min_score', 75),
  tier2_min_score: num('tier2_min_score', 45),
  rule_weight: num('rule_weight', 0.6),
  max_score_gap: num('max_score_gap', 35),
  calendly_tier1: str('calendly_link_tier1', 'https://calendly.com/your-team/enterprise-demo'),
  calendly_tier2: str('calendly_link_tier2', 'https://calendly.com/your-team/intro-call'),
  lemlist_campaign_id: str('lemlist_campaign_id', ''),
  smartlead_campaign_id: str('smartlead_campaign_id', ''),
  icp_description: str('icp_description', 'B2B companies with 50+ employees in operations-heavy industries.'),
};

const enrichMap = {};
enrichRows.forEach(e => { if (e.domain) enrichMap[String(e.domain).trim().toLowerCase()] = e; });

return leads.map(l => {
  const e = enrichMap[l.domain] || null;
  const emp = e ? toNum(e.employees) : toNum(l.hint_employees);
  const rev = e ? toNum(e.annual_revenue_usd) : null;
  const industry = e ? String(e.industry || '').trim() : '';

  const flags = {
    personal_email: FREE.includes(l.email_domain),
    invalid_email: !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(l.email),
    enrichment_not_found: !e,
  };

  // size 0-30
  const sizePts = emp === null ? 0 : emp >= T1_EMP ? 30 : emp >= T2_EMP ? 18 : emp >= 10 ? 8 : 2;
  // revenue 0-25
  const revPts = rev === null ? 0 : rev >= T1_REV ? 25 : rev >= T2_REV ? 15 : rev >= 1000000 ? 6 : 2;
  // title seniority 0-25
  const t = (l.job_title || '').toLowerCase();
  let titlePts = 0, titleLevel = 'missing';
  if (t) {
    if (hasKw(t, DQ)) { titlePts = 0; titleLevel = 'disqualified'; }
    else if (hasKw(t, EXEC)) { titlePts = 25; titleLevel = 'exec'; }
    else if (hasKw(t, DIR)) { titlePts = 20; titleLevel = 'director'; }
    else if (hasKw(t, MGR)) { titlePts = 12; titleLevel = 'manager'; }
    else { titlePts = 5; titleLevel = 'individual'; }
  }
  // industry 0-10
  const indPts = !industry ? 0 : INDUSTRIES.includes(industry.toLowerCase()) ? 10 : 3;
  // email quality 0-10
  const emailPts = (flags.personal_email || flags.invalid_email) ? 0 : 10;

  const rule_score = Math.max(0, Math.min(100, sizePts + revPts + titlePts + indPts + emailPts));

  return { json: {
    ...l,
    company_enriched_name: e ? e.company_name : '',
    employees: emp, annual_revenue_usd: rev, industry,
    country: e ? (e.country || '') : '',
    funding_stage: e ? (e.funding_stage || '') : '',
    tech_signals: e ? (e.tech_signals || '') : '',
    enrichment_status: e ? 'enriched' : 'not_found',
    title_level: titleLevel,
    flags, rule_score,
    score_breakdown: { size: sizePts, revenue: revPts, title: titlePts, industry: indPts, email: emailPts },
    cfg,
  }};
});

// Combines rule score + AI judgement into the final tier and route.
const base = $('Calculate Enrichment Score').item.json;

// 1. Point to $json.answers instead of$json.output
const ai = $json.answers || null;

// 2. Validate using the nested structure
const aiScoreRaw = ai?.ai_score?.score;
const aiTier = ai?.ai_tier?.choice;
const conf = ai?.confidence?.choice || 'none';
const aiOk = typeof aiScoreRaw === 'number' && typeof aiTier === 'string';

const cfg = base.cfg;

// 3. Normalize AI score from 0-4 scale to 0-100 scale to match rule_score
const aiScore = aiOk ? Math.round(aiScoreRaw * 25) : null;
const combined = aiOk 
  ? Math.round(cfg.rule_weight * base.rule_score + (1 - cfg.rule_weight) * aiScore) 
  : base.rule_score;
const gap = aiOk ? Math.abs(base.rule_score - aiScore) : null;

let tier, route, reason, action;

if (base.flags.personal_email || base.flags.invalid_email) {
  tier = 'Unqualified_Personal_Email'; 
  route = 'unqualified';
  reason = base.flags.invalid_email ? 'Invalid email address' : 'Personal/free email domain';
  action = 'Added to generic Smartlead nurture';
} else if (!aiOk) {
  tier = 'Needs_Review'; 
  route = 'review';
  reason = 'AI judge failed or returned invalid output';
  action = 'Sent to Slack review channel';
} else if (gap > cfg.max_score_gap) {
  tier = 'Needs_Review'; 
  route = 'review';
  reason = `Rule score (${base.rule_score}) and AI score (${aiScore}) disagree by ${gap}`;
  action = 'Sent to Slack review channel';
} else if (combined >= cfg.tier1_min_score && aiTier === 'Tier_1_Enterprise') {
  tier = 'Tier_1_Enterprise'; 
  route = 'tier1';
  reason = `Combined score ${combined} and AI agrees on Tier 1`;
  action = 'WhatsApp Calendly link + Slack AE alert';
} else if (combined >= cfg.tier2_min_score && aiTier !== 'Unqualified') {
  tier = 'Tier_2_MidMarket'; 
  route = 'tier2';
  reason = `Combined score ${combined} meets mid-market threshold`;
  action = 'Soft-touch email + Lemlist warm sequence';
} else if (base.flags.enrichment_not_found && conf === 'low') {
  tier = 'Needs_Review'; 
  route = 'review';
  reason = 'No enrichment data and AI confidence is low';
  action = 'Sent to Slack review channel';
} else {
  tier = 'Unqualified_Low_Fit'; 
  route = 'unqualified';
  reason = `Combined score ${combined} below threshold or AI says unqualified`;
  action = 'Added to generic Smartlead nurture';
}

return {
  json: {
    ...base,
    ai_score: aiScore,
    ai_tier: aiTier || '',
    ai_confidence: conf,
    buying_signals: ai?.has_buying_signals?.noul != null ? String(ai.has_buying_signals.noul) : '',
    red_flags: ai?.has_red_flags?.noul != null ? String(ai.has_red_flags.noul) : '',
    combined_score: combined,
    score_gap: gap,
    final_tier: tier,
    route,
    route_reason: reason,
    action_taken: action,
    flag_summary: Object.keys(base.flags).filter(k => base.flags[k]).join(', ')
  }
};

