parameters.jsCode:
const rows = $('Determine Final Tier').all().map(i => i.json);
const by = {};
rows.forEach(r => { by[r.final_tier] = (by[r.final_tier] || 0) + 1; });
const avg = rows.length ? Math.round(rows.reduce((s, r) => s + (r.combined_score || 0), 0) / rows.length) : 0;
const hot = rows.filter(r => r.route === 'tier1').map(r => r.full_name + ' @ ' + r.company_name + ' (' + r.combined_score + ')');
const review = rows.filter(r => r.route === 'review').map(r => r.full_name + ' - ' + r.route_reason);
return [{ json: {
  run_at: new Date().toISOString(),
  leads_processed: rows.length,
  by_tier: by,
  avg_combined_score: avg,
  tier1_leads: hot,
  needs_review: review,
}}];

