={
  "model": "jev-1.13-free",
  "state": {
    "icp_description": {{ JSON.stringify($json.cfg?.icp_description || $json.icp_description || 'B2B SaaS companies with >50 employees') }},
    "lead_name": {{ JSON.stringify($json.full_name || $json.lead_name || '') }},
    "job_title": {{ JSON.stringify($json.job_title || 'unknown') }},
    "email_type": {{ JSON.stringify($json.email_type || ($json.flags?.personal_email ? 'personal/free' : ($json.flags?.invalid_email ? 'invalid' : 'business'))) }},
    "company_name": {{ JSON.stringify($json.company_enriched_name || $json.company_name || 'unknown') }},
    "domain": {{ JSON.stringify($json.domain || '') }},
    "employees": {{ JSON.stringify($json.employees ?? 'unknown') }},
    "annual_revenue_usd": {{ JSON.stringify($json.annual_revenue_usd ?? 'unknown') }},
    "industry": {{ JSON.stringify($json.industry || 'unknown') }},
    "country": {{ JSON.stringify($json.country || 'unknown') }}
  },
  "questions": {
    "ai_score": {
      "type": "score",
      "instructions": "Rate the ICP fit and buying intent on an ordinal scale.",
      "criteria": [
        "Unqualified: student, personal email, vendor, or off-ICP industry",
        "Low fit: micro-business or non-decision maker",
        "Moderate fit: mid-market account or operational buyer fit",
        "Strong fit: high-growth ICP company with key influencer",
        "Tier 1 Enterprise: enterprise account with executive decision-maker"
      ]
    },
    "ai_tier": {
      "type": "choice",
      "instructions": "Classify lead tier.",
      "criteria": {
        "Tier_1_Enterprise": "Large account with 1000+ employees or $200M+ revenue, decision-maker or key influencer",
        "Tier_2_MidMarket": "Mid-market account with 50+ employees or $5M+ revenue, or operational buyer fit",
        "Unqualified": "Student, personal/free email, vendor, off-ICP industry, or micro-business"
      }
    },
    "confidence": {
      "type": "choice",
      "instructions": "Confidence level in the assessment.",
      "criteria": {
        "high": "Enrichment data is present, role is verified, and buying signals are clear",
        "medium": "Core fields match but company size or revenue is estimated",
        "low": "Missing key enrichment, unverified title, or conflicting signals"
      }
    },
    "has_buying_signals": {
      "type": "noul",
      "instructions": "Does this lead show clear positive buying signals based on company size and role?"
    },
    "has_red_flags": {
      "type": "noul",
      "instructions": "Are there disqualifying red flags in this profile?"
    }
  }
}
